from pathlib import Path
import json,hashlib,array,sys
R=Path(__file__).resolve().parents[1];A=R/'migrations/shared-nms002-l02-p042/audit'
b=json.loads((A/'source-audio-blocks-v1.json').read_text());p=json.loads((A/'source-pcm-v1.json').read_text());raw=(A/'source-pcm-v1.f32').read_bytes();assert hashlib.sha256(raw).hexdigest()==p['sha256'];samples=array.array('f');samples.frombytes(raw)
rows=b['blocks'];assert len(rows)==618 and len(samples)==1132992
starts={};cursor=0
for row in rows:starts[row['frame']]=cursor+row['seekSamples'];cursor+=row['sampleCount']
assert [starts[f]for f in [7,9,502]]==[1673,3510,903391]
# Preserve complete PCM between resumed stream anchors; never cut encoded MP3.
segments=[]
for frame,start,end in [(7,1673,3510),(9,3510,903391),(502,903391,len(samples))]:
 outputStart=round((frame-1)*22050/12);segments.append({'frame':frame,'sourceStart':start,'sourceEnd':end,'outputStart':outputStart,'outputEnd':outputStart+end-start})
stopSamples=624*22050//12;tailStart=segments[-1]['sourceStart']+stopSamples-segments[-1]['outputStart'];assert tailStart==1129403
assert all(v==0 for v in samples[tailStart:]);assert all(v==0 for v in samples[:1673]);assert all(v==0 for v in samples[900860:903391])
plan={'sourceSha256':b['encodedStream']['sha256'],'sourceBytes':b['encodedStream']['bytes'],'sampleRate':22050,'channels':1,'decodedSamples':len(samples),'latencySamples':1673,'totalSamples':stopSamples,'fullScheduledSamples':segments[-1]['outputEnd'],'silentTailStart':tailStart,'segments':segments}
receipt={'sourceSwfSha256':b['sourceSha256'],'pcmSha256':p['sha256'],'plan':plan,'qualifications':['Full MP3 decoded once before source-frame scheduling.','Three contiguous source PCM segments; source resume anchors frames 7,9,502.','Empty frame 499 negative seek points into verified zero PCM, not an additional segment.','Half-sample frame 502 placement rounds to sample 920588.','Stop occurs on entry to frame 625 at 52 seconds; only verified exact-zero scheduled tail is omitted. Original decoded source is retained.','Header sampleSize 1837 differs from 22050/12; no internal PCM samples dropped or duplicated. Runtime synchronization and listening acceptance remain pending.'],'audioAccepted':False}
outputs={A/'native-audio-plan-v1.json':json.dumps(receipt,indent=2)+'\n',R/'packages/demos/src/generated/nms-l02-p042-audio-plan-v1.ts':'// Generated by scripts/generate-nms-l02-p042-audio-plan-v1.py; do not edit.\nexport const P042_AUDIO_SOURCE = '+json.dumps(plan,separators=(',',':'))+' as const;\n'}
for dest,s in outputs.items():
 if '--check'in sys.argv:assert dest.read_text()==s
 elif dest.exists():assert dest.read_text()==s
 else:dest.write_text(s)
print(json.dumps({'status':'PASS','segments':segments,'silentTailSamples':len(samples)-tailStart,'duration':stopSamples/22050}))
